<script setup lang="ts">
import {computed,onMounted,ref,nextTick,watch} from 'vue'
import {localFetch} from './http'
import {vRememberDisclosure} from './rememberDisclosure'
import {validateEvening,signal} from './v6EveningForecast'
import type {EveningReport,Metric,Target} from './v6EveningForecast'
const props=defineProps<{payload?:EveningReport}>(),data=ref<EveningReport|null>(props.payload?validateEvening(props.payload):null),error=ref(''),cached=ref(false),horizon=ref(1),selectedYear=ref(0)
const latest=computed(()=>data.value?.latest),observation=computed(()=>latest.value?.observation),season=computed(()=>observation.value?.seasonality),cases=computed(()=>observation.value?.yearAnalogs.cases||[])
const time=(s?:string)=>s?s.slice(0,19).replace('T',' '):'沒有保存時間'
const pct=(p:number)=> (p*100).toFixed(1)+'%',level=(n:number)=>n.toLocaleString('zh-TW',{maximumFractionDigits:0}),signed=(n:number)=>(n>0?'+':'')+level(n)
const decimal=(n:number|null|undefined)=>n==null?'資料不足':(n>0?'+':'')+n.toFixed(2)+'%'
const score=(n:number|null)=>n==null?'尚無到期樣本':n.toFixed(4)
const accuracy=(m:Metric)=>{const s=signal(m);return !s||!s.signals?'無方向出手（0筆）':pct(s.accuracy!)+`（${s.correct}/${s.signals}）`}
const label=(d:string)=>d==='up'?'看漲':d==='down'?'看跌':'無方向（未達65%）'
const rows=computed(()=>[...(data.value?.history||[])].reverse())
const observations=computed(()=>(data.value?.history||[]).filter(f=>f.targets[horizon.value-1]?.model==='OBS'&&f.targets[horizon.value-1]?.methodVersion===latest.value?.targets[horizon.value-1]?.methodVersion))
const currentSeries=computed(()=>observations.value.filter(f=>f.anchorDate===latest.value?.anchorDate&&f.targets[horizon.value-1]?.targetDate===latest.value?.targets[horizon.value-1]?.targetDate))
function delta(t:Target){const prior=[...(data.value?.history||[])].reverse().find(f=>f.id!==latest.value?.id&&f.anchorDate===latest.value?.anchorDate&&f.targets[t.horizon-1]?.targetDate===t.targetDate&&f.targets[t.horizon-1]?.model===t.model&&f.targets[t.horizon-1]?.methodVersion===t.methodVersion);return prior?`${((t.up-prior.targets[t.horizon-1]!.up)*100)>=0?'+':''}${((t.up-prior.targets[t.horizon-1]!.up)*100).toFixed(1)} 個百分點`:'此方法首次保存'}
const chartWidth=computed(()=>Math.max(650,currentSeries.value.length*95)),x=(i:number)=>55+(chartWidth.value-90)*i/Math.max(1,currentSeries.value.length-1),y=(p:number)=>190-p*155
function line(up:boolean){return currentSeries.value.map((f,i)=>{const p=f.targets[horizon.value-1]!.up;return `${i?'H '+x(i)+' V':'M '+x(i)} ${y(up?p:1-p)}`}).join(' ')}
const colors=['#b76658','#4f876e','#a07e33','#6488a0','#a578a3']
const yearExtent=computed(()=>Math.max(5,...cases.value.flatMap(c=>c.path.map(p=>Math.abs(p.pct))))),yearY=(p:number)=>100-p/yearExtent.value*78
const yearLine=(path:{day:number;pct:number}[])=>path.map((p,i)=>`${i?'L':'M'} ${55+p.day/60*590} ${yearY(p.pct)}`).join(' ')
const chartScroller=ref<HTMLElement|null>(null)
function newest(){const el=chartScroller.value;if(el)el.scrollLeft=el.scrollWidth}
watch(()=>data.value?.latest?.id,()=>nextTick(newest),{immediate:true})
const progress=(role:string)=>data.value?.progress.find(p=>p.role===role)
onMounted(async()=>{
 if(props.payload)return
 try{const r=await localFetch('/v6-research/evening-forecast.json');if(!r.ok)throw Error('預報顯示檔尚未讀取');data.value=validateEvening(await r.json());try{localStorage.setItem('branch-monitor:v6:evening:last-good:v1',JSON.stringify(data.value))}catch{}}
 catch(e){error.value=(e as Error).message;try{const prior=localStorage.getItem('branch-monitor:v6:evening:last-good:v1');if(prior){data.value=validateEvening(JSON.parse(prior));cached.value=true}}catch{}}
})
</script>
<template>
 <section class="evening-forecast" aria-label="18點22點逐日收盤預報">
  <header><div><small>V6 · LIVE OBSERVATION</small><h2>T+1／T+2／T+3 漲跌觀察</h2><p>使用最新可核對行情與月份位置計算；未訓練、未校準，不代表已驗證的勝率。</p></div><span class="version">{{latest?.roleLabel||'讀取已保存版本'}}</span></header>
  <p v-if="cached" class="notice">目前連線未取得新檔，保留上次有效值與舊保存時間，沒有冒充本次重算。</p><p v-else-if="error" class="notice">{{error}}</p>
  <template v-if="latest">
   <div class="basis"><b>T＝{{latest.anchorDate}} 加權收盤 {{level(latest.anchorClose)}} 點</b><span>資訊截點 {{time(latest.informationCutoff)}} · 實際保存 {{time(latest.savedAt)}} · 美國 {{latest.usTimeRegime}}</span></div>
   <p class="notice">{{observation?'未校準觀察版：主數字會隨可用夜盤、波動與月份資料變化。固定規則尚未證明能提高命中率；M0只保留作研究比較。':'以下為先前保存的基準紀錄，尚未保存新的觀察版。'}}</p>
   <div v-if="observation" class="inputs"><template v-if="observation.inputs.night"><b>{{observation.inputs.night.contract}} 夜盤 {{level(observation.inputs.night.price)}} 點 · 較同合約日盤 {{decimal(observation.inputs.night.change_day_pct)}}</b><span>報價 {{time(observation.inputs.night.quote_at)}} · 日盤 {{level(observation.inputs.night.day_close)}} 點</span></template><b v-else>本次缺可核對的新鮮夜盤，只用現貨狀態與月份觀察；沒有套用舊夜盤。</b><span>計算用日波動 {{observation.inputs.sigmaPct.toFixed(2)}}% · 海外與夜盤分歧僅放寬不確定性，避免重複計入同一消息。</span></div>
   <div class="forecast-cards"><article v-for="t in latest.targets" :key="t.horizon" :data-horizon="t.horizon">
    <div class="card-title"><b>T+{{t.horizon}}</b><strong>{{t.targetDate}}</strong></div><small class="model">{{t.modelLabel}} · {{latest.roleLabel}}</small>
    <div class="odds"><div class="up"><span>觀察上漲機率</span><b>{{pct(t.up)}}</b></div><div class="down"><span>觀察下跌機率</span><b>{{pct(t.down)}}</b></div></div>
    <p class="change">上漲較前次：{{delta(t)}}</p><div class="direction" :class="t.direction">{{label(t.direction)}}</div>
    <div class="price"><span>收盤觀察中位數（第50百分位）</span><b>{{level(t.medianClose)}} 點</b><small>對 T 累積 {{signed(t.medianChangePoints)}} 點</small></div>
    <p class="interval">第10～90百分位觀察範圍<b>{{level(t.q10Close)}}～{{level(t.q90Close)}} 點</b><span>對 T 累積 {{signed(t.q10ChangePoints)}}～{{signed(t.q90ChangePoints)}} 點</span><small>含部分夜盤未結束的壓力情境，尚未驗證80%實際涵蓋。</small></p>
    <p class="method-status">{{t.model==='OBS'?'未訓練／未校準，歷史命中率尚不可用；保存後逐筆核對。':'先前保存的基準版本，不是新的夜盤觀察。'}}</p>
   </article></div>
   <p>機率、中位數、區間來自同一份分布；T+2／T+3點數均對同一個T起點累積，不能再加上前一張卡的點數。</p>
   <section class="probability-history"><div class="section-title"><h3>每次更新的漲跌機率變化</h3><select aria-label="機率走勢期限" v-model.number="horizon"><option v-for="h in [1,2,3]" :key="h" :value="h">T+{{h}}</option></select></div><p>同起點、同到期日比較；不同方法不連線。本次起點已有 {{currentSeries.length}} 筆觀察保存，只有一筆時不補造前次值。</p><button class="latest-button" @click="newest">回到最新</button><div class="scroll" ref="chartScroller"><svg :width="chartWidth" height="240" role="img" aria-label="觀察版上漲與下跌機率階梯圖"><g v-for="p in [0,.25,.5,.75,1]" :key="p"><line x1="50" :x2="chartWidth-20" :y1="y(p)" :y2="y(p)" stroke="#e5eadf" :stroke-dasharray="p===.5?'4 4':undefined"/><text x="5" :y="y(p)+4">{{pct(p)}}</text></g><path :d="line(true)" fill="none" stroke="#ba6f60" stroke-width="2"/><path :d="line(false)" fill="none" stroke="#548872" stroke-width="2"/><g v-for="(f,i) in currentSeries" :key="f.id"><circle :cx="x(i)" :cy="y(f.targets[horizon-1]!.up)" r="4" fill="#ba6f60"><title>{{time(f.savedAt)}} 上漲 {{pct(f.targets[horizon-1]!.up)}}</title></circle><circle :cx="x(i)" :cy="y(f.targets[horizon-1]!.down)" r="4" fill="#548872"/><text :x="x(i)" y="218" text-anchor="middle">{{f.savedAt.slice(5,16).replace('T',' ')}}</text></g></svg></div><p><span class="up">● 上漲</span>　<span class="down">● 下跌</span>　只在你到對話更新時新增，不隨頁面重整改寫。</p></section>
   <section v-if="season" class="season"><h3>月份位置 · {{season.month}}月與全年比較</h3><p>月份統計原始月末資料自 {{season.monthlyHistoryFirst}}；歷年統計只讀T之前完整年份／月份，本月最新位置用T收盤重算。</p><div class="season-grid"><article><span>本月迄今</span><b>{{decimal(season.currentMonthPct)}}</b><small>完整歷年月均 {{decimal(season.monthStats.meanPct)}}<br/>與完整月平均差 {{season.monthDeviationPp==null?'資料不足':season.monthDeviationPp.toFixed(2)+' 個百分點'}}</small></article><article><span>歷年{{season.month}}月 · {{season.monthStats.n}}年</span><b>{{season.monthStats.upRate==null?'資料不足':pct(season.monthStats.upRate)}} 上漲</b><small>月底報酬最高 {{decimal(season.monthStats.maxPct)}}<br/>最低 {{decimal(season.monthStats.minPct)}}<br/>標準差 {{season.monthStats.stdPct?.toFixed(2)}}%</small></article><article><span>今年迄今</span><b>{{decimal(season.currentYtdPct)}}</b><small>完整歷年全年平均 {{decimal(season.annualStats.meanPct)}}<br/>全年最高／最低 {{decimal(season.annualStats.maxPct)}}／{{decimal(season.annualStats.minPct)}}<br/>共 {{season.annualStats.n}} 個完整年度</small></article></div><p>{{season.comparisonNote}}極值不是未來漲跌的上限／下限，也不是平均回歸保證。</p></section>
   <section v-if="observation" class="analogs"><h3>接近哪些歷史年份 · 同進度比較</h3><p>{{observation.yearAnalogs.description||'同進度歷史不足，未拼接不完整年份。'}}</p><div v-if="cases.length" class="scroll"><table><thead><tr><th>相近順序／年份</th><th>比對到當年</th><th>月迄今／年迄今</th><th>距離</th><th v-for="n in [1,3,5,20,60]" :key="n">之後{{n}}交易日</th></tr></thead><tbody><tr v-for="(c,i) in cases" :key="c.year" @click="selectedYear=c.year" :class="{'selected-year':selectedYear===c.year}"><td :style="{color:colors[i]}">{{c.rank}} · {{c.year}}年</td><td>{{c.matchedThrough}}</td><td>{{decimal(c.mtdPct)}}／{{decimal(c.ytdPct)}}</td><td>{{c.distance.toFixed(2)}}</td><td v-for="o in c.outcomes" :key="o.sessions" :title="o.date">{{decimal(o.returnPct)}}</td></tr></tbody></table></div><div v-if="cases.length" class="scroll"><svg width="700" height="220" role="img" aria-label="相近年份後60交易日實際漲跌"><line x1="55" x2="645" y1="100" y2="100" stroke="#cbd7c7"/><text x="5" y="25">+{{yearExtent.toFixed(0)}}%</text><text x="12" y="104">0%</text><text x="5" y="184">−{{yearExtent.toFixed(0)}}%</text><path v-for="(c,i) in cases" :key="c.year" :d="yearLine(c.path)" fill="none" :stroke="colors[i]" :stroke-width="selectedYear===c.year?3:1.5" :opacity="selectedYear&&selectedYear!==c.year?.3:1" @click="selectedYear=c.year"><title>{{c.year}}年</title></path><text v-for="n in [0,20,40,60]" :key="n" :x="55+n/60*590" y="207" text-anchor="middle">{{n}}交易日</text></svg></div><p>{{observation.yearAnalogs.outcomeNote}}相似度不是機率；排名第一仍可能差異很大。距離為已走完特徵的標準化均方距離，不是重演機率。</p></section>
   <details v-if="observation" v-remember-disclosure="'v6.observation.inputs.v1'" class="details"><summary>本次來源與海外分歧查核</summary><p>美股／ADR不再次疊加為報酬；標普、費半、台積電ADR與夜盤方向分歧才放寬波動。其他已核對報價只作參考。</p><div class="scroll"><table><thead><tr><th>來源</th><th>相對來源前收</th><th>報價時間（台北）</th></tr></thead><tbody><tr v-for="r in observation.inputs.overseas" :key="r.label"><td>{{r.label}}</td><td>{{decimal(r.change_pct)}}</td><td>{{time(r.quote_at)}}</td></tr></tbody></table></div></details>
   <section class="forward"><h3>觀察版到期核對 · 與舊模型分開</h3><p>尚未證實觀察版優於基準；不套用舊模型命中率，也不列入已驗證模型正式60筆。</p><div class="forward-grid"><article v-for="role in ['18_formal','22_supplement','22_revision','unqualified']" :key="role"><b>{{progress(role)?.label}} · 已保存 {{progress(role)?.saved||0}}次</b><p v-for="h in progress(role)?.horizons||[]" :key="h.horizon">T+{{h.horizon}}：已成熟 {{h.n}}筆 · 65%方向命中 {{accuracy(h)}} · Brier {{score(h.brier)}}<br/>80%實際涵蓋 {{h.coverage80==null?'尚無到期樣本':pct(h.coverage80)}}</p></article></div></section>
   <details v-remember-disclosure="'v6.observation.revisions.v1'" class="details"><summary>所有保存、實際收盤與不同方法原值</summary><div class="scroll"><table><thead><tr><th>實際保存／資訊截點</th><th>版本</th><th>起點／到期日</th><th>上漲／下跌</th><th>中位數／10～90範圍</th><th>實際收盤</th><th>方法</th></tr></thead><tbody><tr v-for="f in rows" :key="f.id"><td>{{time(f.savedAt)}}<small>{{time(f.informationCutoff)}} · {{f.usTimeRegime}}</small></td><td>{{f.roleLabel}}</td><td>{{f.anchorDate}}<small>→ {{f.targets[horizon-1]!.targetDate}}</small></td><td>{{pct(f.targets[horizon-1]!.up)}}／{{pct(f.targets[horizon-1]!.down)}}</td><td>{{level(f.targets[horizon-1]!.medianClose)}}<small>{{level(f.targets[horizon-1]!.q10Close)}}～{{level(f.targets[horizon-1]!.q90Close)}}</small></td><td>{{f.targets[horizon-1]!.outcome?level(f.targets[horizon-1]!.outcome!.actualClose):'待到期／待核對'}}</td><td>{{f.targets[horizon-1]!.modelLabel}}</td></tr></tbody></table></div></details>
   <details v-remember-disclosure="'v6.observation.method.v1'" class="details"><summary>觀察方法、未驗證選擇與M0研究比較</summary><p>這不是已訓練的18／22模型。以當下同合約夜盤漲跌作現貨跳空代理，再用過去現貨開盤後的實際報酬和當時波動、回撤、20日強弱加權。現貨開盤代理不等於歷史同時刻夜盤資料。</p><p>同月份權重1.5倍；完整歷史月均以固定10%比重折成日偏移。25%分布放入對稱壓力情境，避免未結束夜盤造成過度確定。這些權重未訓練、未校準，也沒有證實1%Brier改善。海外資料不與夜盤重複疊加報酬；相似年份後續報酬不進入機率。</p><div class="scroll"><table><thead><tr><th>期限</th><th>本次觀察上漲</th><th>M0比較上漲</th><th>舊M0歷史Brier</th></tr></thead><tbody><tr v-for="t in latest.targets" :key="t.horizon"><td>T+{{t.horizon}}</td><td>{{pct(t.up)}}</td><td>{{pct(t.M0Up)}}</td><td>{{score(t.historical.M0.brier)}} · 僅基準成績</td></tr></tbody></table></div><p v-if="observation">方法版本 {{observation.methodVersion}}。{{observation.inputs.nightNote}} {{observation.inputs.overseasNote}}</p></details>
  </template>
 </section>
</template>
<style scoped>
