t;border-top:1px solid #e7ece0;padding-top:13px}.interval b,.interval span,.interval small{display:block}.interval b{font-size:15px;color:#5d7b5d;margin:5px 0}.interval small{margin-top:8px;font-size:10px}.method-status{font-size:10px!important}.forward,.season,.analogs,.probability-history{border-top:1px solid #e2e9db;padding-top:14px;margin-top:20px;min-width:0}.season-grid span,.season-grid b,.season-grid small{display:block}.season-grid span{font-size:11px;color:#85917d}.season-grid b{font-size:22px;margin:10px 0}.season-grid small{font-size:11px;line-height:1.9;color:#839079}.forward-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.forward-grid article{padding:14px;background:#f5f8f1;border-radius:9px}.forward-grid b{font-size:12px}.forward p{font-size:11px}.details{border-top:1px solid #e1e8db;margin-top:17px;padding-top:16px;min-width:0;font-size:11px;color:#849379}.details summary{font-size:12px;cursor:pointer;font-weight:600}.scroll{max-width:100%;overflow-x:auto;margin-top:15px;min-width:0;overscroll-behavior-x:contain}.scroll svg{display:block;max-width:none}.scroll svg text{font-size:10px;fill:#85917d}.scroll table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:11px}.scroll th,.scroll td{padding:11px 13px;border-bottom:1px solid #e6ecdf;text-align:left}.scroll th{background:#f6f8f1;font-size:10px;color:#8d9d82}.scroll small{display:block;font-size:10px;color:#97a38c;margin-top:5px}.analogs tbody tr{cursor:pointer}.selected-year{background:#f0f5eb}.latest-button{font:inherit;font-size:11px;background:white;border:1px solid #dce5d6;border-radius:7px;padding:7px;color:inherit;cursor:pointer}select{padding:7px;border:1px solid #dce5d6;border-radius:7px;color:inherit;background:white}@media(max-width:850px){.forecast-cards,.season-grid{grid-template-columns:1fr}.forward-grid{grid-template-columns:1fr}}@media(max-width:500px){.evening-forecast{padding:15px}.evening-forecast header{flex-wrap:wrap}.evening-forecast h2{font-size:20px}.odds b{font-size:29px}}
